INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (1, 'MULTIPLE_FACES', 'LIVENESS', 422, 'Only one face should be visible in the camera.', 'يجب أن يظهر وجه واحد فقط أمام الكاميرا.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (2, 'FACE_TOO_SMALL', 'LIVENESS', 422, 'Move closer so your face fills the guide.', 'اقترب أكثر حتى يملأ وجهك الإطار.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (3, 'BLURRY', 'LIVENESS', 422, 'The photo is blurry. Hold the phone steady and try again.', 'الصورة غير واضحة. ثبّت الهاتف وحاول مرة أخرى.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (4, 'TOO_DARK', 'LIVENESS', 422, 'It is too dark. Move to a brighter place and try again.', 'الإضاءة ضعيفة. انتقل إلى مكان أكثر إضاءة وحاول مرة أخرى.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (5, 'TOO_BRIGHT', 'LIVENESS', 422, 'There is too much light on your face. Avoid strong light and try again.', 'الإضاءة على وجهك قوية جدًا. تجنّب الضوء المباشر وحاول مرة أخرى.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (6, 'HEAD_TURNED', 'LIVENESS', 422, 'Look straight at the camera.', 'انظر مباشرة إلى الكاميرا.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (7, 'HEAD_TILTED', 'LIVENESS', 422, 'Keep your head level and look straight at the camera.', 'حافظ على استقامة رأسك وانظر مباشرة إلى الكاميرا.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (8, 'SPOOF_SUSPECTED', 'LIVENESS', 422, 'Liveness check failed: please use your real face, not a photo or a screen.', 'فشل التحقق من الحيوية: يرجى استخدام وجهك الحقيقي وليس صورة أو شاشة.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (9, 'FACE_CHANGED', 'LIVENESS', 422, 'The face changed between the two steps. Please complete the check yourself, without switching people.', 'تغيّر الوجه بين الخطوتين. يرجى إكمال التحقق بنفسك دون تبديل الأشخاص.', ${now}, ${now});
INSERT INTO ref_reason_code (id, code, category, http_status, message_en, message_ar, created_at, updated_at) VALUES (10, 'NOT_CLOSER', 'LIVENESS', 422, 'We could not confirm that you moved closer. Please try again.', 'لم نتمكن من التأكد من أنك اقتربت من الكاميرا. يرجى المحاولة مرة أخرى.', ${now}, ${now});
